0 & 0 & -2\lambda & (1+2\lambda+2\beta) \end{bmatrix}

\mathbf{AA3} = \begin{bmatrix}
-\beta & 0 & 0 & 0 \\
0 & -\beta & 0 & 0 \\
0 & 0 & -\beta & 0 \\
0 & 0 & 0 & -\beta \end{bmatrix}

\mathbf{BB1} = \begin{bmatrix}
